class TestArtifactStatus:
    """Test ArtifactStatus enum integrity."""

    def test_enum_values(self):
        """Verify all expected enum values exist."""
        expected_values = {
            "PENDING": "pending",
            "APPROVED": "approved",
            "TESTED": "tested",
            "INTEGRATED": "integrated",
            "REJECTED": "rejected",
            "FAILED": "failed",
        }
        for name, value in expected_values.items():
            assert hasattr(ArtifactStatus, name), f"Missing enum value: {name}"
            assert getattr(ArtifactStatus, name).value == value

    def test_enum_membership(self):
        """Verify enum contains only expected members."""
        members = set(ArtifactStatus.__members__.keys())
        expected = {"PENDING", "APPROVED", "TESTED", "INTEGRATED", "REJECTED", "FAILED"}
        assert members == expected

    def test_enum_from_string(self):
        """Verify string-to-enum conversion."""
        assert ArtifactStatus("pending") == ArtifactStatus.PENDING
        assert ArtifactStatus("approved") == ArtifactStatus.APPROVED
        assert ArtifactStatus("tested") == ArtifactStatus.TESTED
        assert ArtifactStatus("integrated") == ArtifactStatus.INTEGRATED
        assert ArtifactStatus("rejected") == ArtifactStatus.REJECTED
        assert ArtifactStatus("failed") == ArtifactStatus.FAILED

    def test_enum_invalid_string(self):
        """Verify invalid string raises ValueError."""
        with pytest.raises(ValueError):
            ArtifactStatus("invalid_status")


