    def test_atomic_write(self, pipeline_instance, temp_workspace):
        """Verify atomic file writes."""
        test_file = temp_workspace["artifacts"] / "test_artifact.json"
        content = {"key": "value", "nested": {"data": [1, 2, 3]}}

        pipeline_instance._atomic_write(test_file, content)

        assert test_file.exists()
        with open(test_file, "r") as f:
            loaded = json.load(f)
        assert loaded == content

    def test_atomic_write_creates_parent_dirs(self, pipeline_instance, temp_workspace):
        """Verify atomic write creates parent directories."""
