class TestPipelineStateMachine:
    """Test pipeline state machine operations."""

    def test_submit_artifact(self, pipeline_instance, temp_workspace):
        """Verify artifact submission."""
        artifact_path = temp_workspace["artifacts"] / "new_artifact.py"
        artifact_path.write_text("print('Hello')")

        record = pipeline_instance.submit_artifact(
            name="new_artifact",
            version="1.0.0",
            file_path=artifact_path,
            metadata={"author": "test"},
        )

        assert record.status == ArtifactStatus.PENDING
        assert record.checksum is not None
        assert record.artifact_id is not None

    def test_submit_artifact_missing_file(self, pipeline_instance, temp_workspace):
        """Verify submission fails for missing file."""
        missing_path = temp_workspace["artifacts"] / "missing.py"

        with pytest.raises(FileNotFoundError):
            pipeline_instance.submit_artifact(
                name="missing",
                version="1.0.0",
                file_path=missing_path,
            )

    def test_submit_artifact_invalid_extension(self, pipeline_instance, temp_workspace):
        """Verify submission rejects disallowed extensions."""
        artifact_path = temp_workspace["artifacts"] / "bad.exe"
        artifact_path.write_bytes(b"MZ")

        with pytest.raises(ValueError):
            pipeline_instance.submit_artifact(
                name="bad",
                version="1.0.0",
                file_path=artifact_path,
            )

    def test_approve_artifact(self, pipeline_instance, sample_artifact_record):
        """Verify artifact approval."""
        pipeline_instance._records[sample_artifact_record.artifact_id] = sample_artifact_record

        result = pipeline_instance.approve_artifact(sample_artifact_record.artifact_id)
        assert result.status == ArtifactStatus.APPROVED

