class TestErrorHandling:
    """Test error handling and edge cases."""

    def test_corrupt_json_database(self, pipeline_instance, temp_workspace):
        """Verify pipeline handles corrupt JSON database."""
        db_path = temp_workspace["db"]
        db_path.write_text("{invalid json content")

        # Should not raise; should start with empty records
        assert pipeline_instance._records == {}

    def test_missing_database_file(self, pipeline_instance, temp_workspace):
        """Verify pipeline handles missing database file."""
        db_path = temp_workspace["db"]
        assert not db_path.exists()

        # Should create empty records
        assert pipeline_instance._records == {}

    def test_database_persistence(self, pipeline_instance, sample_artifact_record):
        """Verify records persist to database."""
        pipeline_instance._records[sample_artifact_record.artifact_id] = sample_artifact_record
        pipeline_instance._save_database()

        # Create new instance to load from disk
        new_pipeline = ArtifactPipeline(config=ArtifactPipelineConfig())
        assert sample_artifact_record.artifact_id in new_pipeline._records

    def test_max_artifacts_limit(self, pipeline_instance, temp_workspace):
        """Verify max artifacts limit is enforced."""
        config = ArtifactPipelineConfig(max_artifacts=2)
        limited_pipeline = ArtifactPipeline(config=config)

        for i in range(2):
            artifact_path = temp_workspace["artifacts"] / f"artifact_{i}.py"
            artifact_path.write_text(f"print({i})")
            limited_pipeline.submit_artifact(
                name=f"artifact_{i}",
                version="1.0.0",
                file_path=artifact_path,
            )

        # Third submission should fail
        artifact_path = temp_workspace["artifacts"] / "artifact_2.py"
        artifact_path.write_text("print(2)")
        with pytest.raises(RuntimeError):
            limited_pipeline.submit_artifact(
                name="artifact_2",
                version="1.0.0",
                file_path=artifact_path,
            )

    def test_duplicate_artifact_id(self, pipeline_instance, sample_artifact_record):
        """Verify duplicate artifact IDs are rejected."""
        pipeline_instance._records[sample_artifact_record.artifact_id] = sample_artifact_record

        with pytest.raises(ValueError):
            pipeline_instance._add_record(sample_artifact_record)


