class TestPerformance:
    """Test pipeline performance characteristics."""

    def test_bulk_submission(self, pipeline_instance, temp_workspace):
        """Verify bulk artifact submission performance."""
        num_artifacts = 50
        for i in range(num_artifacts):
            artifact_path = temp_workspace["artifacts"] / f"bulk_{i}.py"
            artifact_path.write_text(f"print({i})")
            pipeline_instance.submit_artifact(
                name=f"bulk_{i}",
                version="1.0.0",
                file_path=artifact_path,
            )

        records = pipeline_instance.list_artifacts()
        assert len(records) == num_artifacts

    def test_concurrent_access(self, pipeline_instance, sample_artifact_record):
        """Verify pipeline handles concurrent access (simulated)."""
        import threading

        errors = []

        def worker():
            try:
                for _ in range(10):
                    pipeline_instance._records[sample_artifact_record.artifact_id] = sample_artifact_record
                    pipeline_instance._save_database()
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker) for _ in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors, f"Concurrent access errors: {errors}"


